SELECT "NYC_2"."Borough" AS "Borough",   "NYC_2"."Complaint_Type" AS "Complaint_Type",   CAST(EXTRACT(QUARTER FROM "NYC_2"."Created_Date") AS BIGINT) AS "qr_Created_Date_ok",   SUM(CAST("NYC_2"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok" FROM "NYC_2" WHERE (("NYC_2"."Borough" >= 'BRONX') AND ("NYC_2"."Borough" <= 'STATEN ISLAND') AND ("NYC_2"."Complaint_Type" IN ('Blocked Driveway', 'Street Condition', 'Street Light Condition'))) GROUP BY "NYC_2"."Borough",   "NYC_2"."Complaint_Type", "qr_Created_Date_ok";
